package com.catsblock.weather.i18n

import java.util.Locale

enum class AppLanguage(val code: String, val label: String, val locale: Locale) {
    English("en", "English", Locale.ENGLISH),
    PtBR("pt-BR", "Português (BR)", Locale("pt", "BR")),
    PtPT("pt-PT", "Português (PT)", Locale("pt", "PT")),
    Spanish("es", "Español", Locale("es")),
    French("fr", "Français", Locale.FRENCH),
    Russian("ru", "Русский", Locale("ru")),
    German("de", "Deutsch", Locale.GERMAN),
    Italian("it", "Italiano", Locale.ITALIAN),
    Korean("ko", "한국어", Locale.KOREAN),
    Indonesian("id", "Bahasa Indonesia", Locale("id", "ID"));

    companion object {
        fun from(code: String?) = entries.firstOrNull { it.code == code } ?: English
    }
}

object I18n {
    @Volatile
    var lang: AppLanguage = AppLanguage.English
}

fun tr(key: String): String {
    val lang = I18n.lang
    if (lang == AppLanguage.English) return englishText[key] ?: key
    return table[key]?.getOrNull(lang.ordinal - 1)?.takeIf { it.isNotEmpty() } ?: englishText[key] ?: key
}

fun leadFull(minutes: Int): String = tr(
    when (minutes) {
        1440 -> "24 hours"
        720 -> "12 hours"
        360 -> "6 hours"
        180 -> "3 hours"
        120 -> "2 hours"
        60 -> "1 hour"
        30 -> "30 minutes"
        else -> "15 minutes"
    }
)

private fun row(key: String, vararg values: String): Pair<String, Array<out String>> = key to values

